<?php
declare(strict_types=1);require __DIR__.'/bootstrap.php';require __DIR__.'/snmp_client.php';
function walk_values(array $c,string $oid):array{$r=snmp_run($c,$oid,true);if(!$r['ok'])throw new RuntimeException('Falha SNMP: '.$r['error']);$v=[];foreach(preg_split('/\R/',$r['output'])?:[]as$line){if(!preg_match('/\.([0-9]+)\s+=\s+(?:STRING:\s+"(.*)"|Counter64:\s+([0-9]+)|INTEGER:\s+(?:[^ (]+\()?([0-9]+)\)?)/',$line,$m))continue;$v[(int)$m[1]]=($m[2]??'')!==''?$m[2]:(int)(($m[3]??'')!==''?$m[3]:$m[4]);}return$v;}
try{$c=addon_config();$names=walk_values($c,'1.3.6.1.2.1.31.1.1.1.1');$in=walk_values($c,'1.3.6.1.2.1.31.1.1.1.6');$out=walk_values($c,'1.3.6.1.2.1.31.1.1.1.10');$oper=walk_values($c,'1.3.6.1.2.1.2.2.1.8');$now=microtime(true);$cache='/var/cache/mkauth-huawei-online/interfaces.json';$previous=is_file($cache)?json_decode((string)file_get_contents($cache),true):[];$current=['time'=>$now,'in'=>$in,'out'=>$out];@file_put_contents($cache,json_encode($current),LOCK_EX);$elapsed=isset($previous['time'])?max(.001,$now-(float)$previous['time']):0;$interfaces=[];foreach($names as$idx=>$name){$rx=$tx=null;if($elapsed>0&&isset($previous['in'][$idx],$previous['out'][$idx],$in[$idx],$out[$idx])){$di=(int)$in[$idx]-(int)$previous['in'][$idx];$do=(int)$out[$idx]-(int)$previous['out'][$idx];if($di>=0&&$do>=0){$rx=$di*8/$elapsed;$tx=$do*8/$elapsed;}}$interfaces[]=['index'=>$idx,'name'=>$name,'up'=>(int)($oper[$idx]??0)===1,'rx_bps'=>$rx,'tx_bps'=>$tx];}json_response(['ok'=>true,'version'=>$c['snmp_version']??'2c','interfaces'=>$interfaces]);}catch(Throwable$e){json_response(['ok'=>false,'error'=>$e->getMessage()],500);}
